def check_log_text_safety(log_message):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_toxic_content(
        TextSegments=[
            {
                'Text': log_message
            }
        ],
        LanguageCode='en'
    )
    return response

from typing import Any, Dict, List, Union


class LogQueryRequest:
    def __init__(self, query: str, start_time: str, end_time: str, fields: List[str]):
        self.query = query
        self.start_time = start_time
        self.end_time = end_time
        self.fields = fields


class LogQueryResponse:
    def __init__(self, status: str, results: List[Dict[str, Any]]):
        self.status = status
        self.results = results


def normalize_log_fields(log_entry: Dict[str, Any], fields: List[str]) -> Dict[str, Any]:
    normalized_entry = {}
    for field in fields:
        if field in log_entry:
            normalized_entry[field] = log_entry[field]
    return normalized_entry


def format_log_response(response: LogQueryResponse) -> List[Dict[str, Any]]:
    formatted_response = []
    for entry in response.results:
        formatted_response.append(normalize_log_fields(entry, ['timestamp', 'level', 'message']))
    return formatted_response

import boto3

class ObservabilityClient:
    def __init__(self, region_name='us-west-2'):
        self.client = boto3.client('logs', region_name=region_name)

    def describe_log_groups(self):
        response = self.client.describe_log_groups()
        return response['logGroups']

    def create_log_group(self, log_group_name):
        self.client.create_log_group(logGroupName=log_group_name)

    def describe_log_streams(self, log_group_name):
        response = self.client.describe_log_streams(logGroupName=log_group_name)
        return response['logStreams']

    def create_log_stream(self, log_group_name, log_stream_name):
        self.client.create_log_stream(logGroupName=log_group_name, logStreamName=log_stream_name)

    def put_log_events(self, log_group_name, log_stream_name, log_events):
        self.client.put_log_events(
            logGroupName=log_group_name,
            logStreamName=log_stream_name,
            logEvents=log_events
        )

